"""Find lines node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ...node_base import Node, NodeContext
from ...node_category import NodeCategory


class FindLinesNode(Node):
    """Find line numbers containing plain text."""

    node_type: ClassVar[str] = 'find_lines_node'
    display_name: ClassVar[str] = 'Find lines'
    default_alias: ClassVar[str] = 'Find lines'
    description: ClassVar[str] = 'Find line numbers containing plain text'
    category: ClassVar[str] = NodeCategory.IO
    primary_family: ClassVar[str] = 'Inputs'
    tags: ClassVar[List[str]] = ['file', 'lines', 'text']
    icon_name: ClassVar[str] = 'file-text'
    color_hint: ClassVar[str] = 'green'
    group: ClassVar[Optional[str]] = 'Text files'
    selector_section: ClassVar[Optional[str]] = 'Files'
    input_ports: ClassVar[List[str]] = ['input']
    output_ports: ClassVar[List[str]] = ['default', 'match_count']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'input': {'name': 'Text to find', 'description': '', 'data_type': 'string', 'required': True, 'sources': ['upstream', 'vault', 'configured']}}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Line numbers', 'description': '', 'data_type': 'var', 'required': True, 'to': ['downstream', 'vault'], 'pass_through': True}, 'match_count': {'name': 'Match count', 'description': 'All matching lines, including those beyond Max matches', 'data_type': 'number', 'required': False, 'to': ['vault']}}
    default_config: ClassVar[Dict[str, Any]] = {'input_source': 'Configured', 'input_vault_key': '', 'input': 'ERROR', 'file': '', 'match_case': True, 'max_matches': 100, 'max_file_mb': 10, 'transient_output': True, 'dead_drop_passthrough': False, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': '', 'match_count_vault_write': False, 'match_count_vault_key': '', 'match_count_vault_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'input_source': {'type': 'select', 'label': 'Input source', 'options': ['Upstream payload', 'Vault', 'Configured'], 'tab': 'Source', 'section': 'Required Inputs'}, 'input_vault_key': {'type': 'string', 'label': 'Input Vault key', 'required': False, 'tab': 'Source', 'section': 'Required Inputs', 'vault_type': 'string', 'visible_when': {'input_source': 'Vault'}}, 'input': {'type': 'string', 'label': 'Text to find', 'tab': 'Parameters', 'description': 'Plain text. Symbols are matched literally.', 'visible_when': {'input_source': 'Configured'}}, 'file': {'type': 'string', 'label': 'File', 'tab': 'Parameters', 'description': 'Only folders allowed in Options.'}, 'match_case': {'type': 'boolean', 'label': 'Match case', 'tab': 'Parameters'}, 'max_matches': {'type': 'integer', 'label': 'Max matches', 'tab': 'Parameters', 'description': 'Keep the latest matches. Match count includes every matching line.', 'min': 1, 'max': 1000}, 'max_file_mb': {'type': 'integer', 'label': 'Max file size (MB)', 'tab': 'Parameters', 'min': 1, 'max': 100}}
    ui_hints: ClassVar[Dict[str, Any]] = {}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'not_allowed', 'description': 'This file is outside the folders allowed in Options.', 'retryable': False}, {'code': 'file_missing', 'description': 'This file was not found.', 'retryable': False}, {'code': 'not_regular', 'description': 'Choose a regular text file.', 'retryable': False}, {'code': 'file_unreadable', 'description': 'This file could not be read.', 'retryable': False}, {'code': 'not_utf8', 'description': 'This file is not UTF-8 text.', 'retryable': False}, {'code': 'file_too_large', 'description': 'This file is too large.', 'retryable': False}, {'code': 'line_too_long', 'description': 'A line in this file is too long.', 'retryable': False}, {'code': 'file_changed', 'description': 'This file changed while reading it.', 'retryable': False}, {'code': 'text_missing', 'description': 'Enter text to find.', 'retryable': False}]

    async def execute(self, context: NodeContext) -> None:
        from ... import text_lines
        from ...node_errors import NodeError
        from ...system_access import finish
        try:
            text_lines.validate_outputs(self.config, extra=True)
            value, count = await text_lines.find(self.config, context)
            if self.config.get('match_count_vault_write'):
                context.memory_bank.store_persistent(self.config['match_count_vault_key'].strip(), count, type_tag='number')
            finish(self, context, value, 'var')
        except NodeError as exc:
            context.signal_error(exc)
